float sq(float v) {return v*v;}
vec2 sq(vec2 v) {return v*v;}
vec3 sq(vec3 v) {return v*v;}
vec4 sq(vec4 v) {return v*v;}

vec3 screen(vec3 a, vec3 b) {return 1.-(1.-a)*(1.-b);}

float circle(in vec2 uv, in vec2 pos, in float r) {
    return 1./sq(sq(sq(abs(r - length(uv - pos))+1.)));
}

mat2 rot(float t) {
    float s = sin(t), c = cos(t);
    return mat2(vec2(c,s), vec2(-s, c));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2.*fragCoord - iResolution.xy)/iResolution.y;
    //uv *= 0.4;// crop for immersion
    uv = normalize(uv)*tan(1.5707963268*min(length(uv),1.));
    vec3 col = vec3(0);

    //+0.4*(2.*iMouse.x - iResolution.x)/iResolution.x;
    const float scale = 0.85;
    const float r = -log(scale);
    const float speed = 2.;
    const float jmax = 9.;
    const float fade = 7.;
    const float f = 0.2*6.;//*speed;
    float size = exp(3.);
    const float q = 3.1/5.;


    for (float i = size*pow(scale,-fract(speed*iTime/r)), j = -fract(speed*iTime/r)*r;
        j < jmax;
        j += r, i *= scale) {
        vec3 c = .5+.5*sin(3.141592*(0.3*(j+scale*speed*iTime)+vec3(0,2,4)/3.));
        c *= smoothstep(-1.,fade-1.,j)*smoothstep(jmax,jmax-fade,j);
        float t = f*(1.4*j+.5*speed*iTime);
        vec2 center = 1.2*i*rot(0.05*speed*iTime)*vec2(cos(q*t), sin(t));
        col = screen(col, circle(uv, center, i)*c);
    }

    fragColor = vec4(pow(col,vec3(1.3)),1);
}
